--
-- Name: create_offboarding_movement_actions(); Type: FUNCTION; Schema: public; Owner: gestion_it
--

CREATE FUNCTION public.create_offboarding_movement_actions() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.type = 'offboarding' THEN
            movement_id,
            action_type,
            label,
            sort_order
        )
        SELECT
            NEW.id,
            template.action_type,
            template.label,
            template.sort_order
        FROM offboarding_action_templates AS template
        WHERE template.is_active = true
          AND NOT EXISTS (
              SELECT 1
              FROM movement_actions AS existing
              WHERE existing.movement_id = NEW.id
                AND existing.action_type = template.action_type
                AND existing.label = template.label
          )
        ORDER BY template.sort_order;
    END IF;

    RETURN NEW;
END;
$$;


